import { getContractRules, getEscalationAudit, getEscalationQueue, getEscalationSnapshots } from './fuelEscalationEngineV3';

const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??f}catch{return f}};
const write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const now=()=>new Date().toISOString();
const currentUser=()=>{const u=read('loginUser',{});return u?.kullanici||u?.kullanici_adi||'Sistem'};
const LOCK='odak_yakit_approval_locks_v4', USER_PERMS='odak_yakit_user_permissions_v4';
const PACKAGE='odak_yakit_packages_v4', MANUAL='odak_yakit_manual_changes_v4';
export const ACTIONS=['view','submit','approve','reject','rules','rollback'];
export const ACTION_LABELS={view:'Görüntüle',submit:'Onaya gönder',approve:'Onayla',reject:'Reddet',rules:'Kural yönet',rollback:'Geri al'};
export const getUserPermissionOverrides=()=>read(USER_PERMS,{});
export const saveUserPermissions=(userId,permissions)=>{const all=getUserPermissionOverrides();all[String(userId)]=permissions;write(USER_PERMS,all);window.dispatchEvent(new Event('odak-escalation-changed'));return all};
export const getEffectiveUserPermissions=(user,rolePermissions)=>getUserPermissionOverrides()[String(user?.id)]||rolePermissions?.[String(user?.rol||'kullanici').toLocaleLowerCase('tr-TR')]||rolePermissions?.kullanici||['view'];
export const thresholdProgress=(customer)=>{const rule=getContractRules()[customer];const rows=getEscalationQueue().filter(x=>x.customer===customer).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const r=rows[0];if(!rule||!r)return {customer,current:0,threshold:Number(rule?.threshold||0),percent:0,remaining:Number(rule?.threshold||0),state:'unknown'};const current=Math.abs(Number(r.fuelChange||0)),threshold=Number(rule.threshold||0),percent=threshold?Math.min(100,(current/threshold)*100):0;return {customer,current,threshold,percent,remaining:Math.max(0,threshold-current),state:current>=threshold?'passed':percent>=80?'near':'safe'};};
export const getOrCreatePackage=(row)=>{if(!row)return null;const all=read(PACKAGE,[]);let p=all.find(x=>x.escalationId===row.id);if(p)return p;const seq=Number(localStorage.getItem('odak_fuel_package_seq')||0)+1;localStorage.setItem('odak_fuel_package_seq',String(seq));p={id:`PKT-${new Date().getFullYear()}-${String(seq).padStart(4,'0')}`,escalationId:row.id,customer:row.customer,lockedFuel:Number(row.newFuel),oldFuel:Number(row.oldFuel),appliedRate:Number(row.appliedRate),created_at:row.created_at||now(),created_by:currentUser()};write(PACKAGE,[p,...all].slice(0,500));return p;};
export const getPackage=(escalationId)=>read(PACKAGE,[]).find(x=>x.escalationId===escalationId)||getOrCreatePackage(getEscalationQueue().find(x=>x.id===escalationId));
export const getCustomerConflict=(customer)=>{const rows=getEscalationQueue().filter(x=>x.customer===customer&&['pending','postponed','suspicious','processing'].includes(x.status)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return {hasConflict:rows.length>1,count:rows.length,rows};};
export const acquireApprovalLock=(id,minutes=10)=>{const all=read(LOCK,{}),me=currentUser(),existing=all[id];if(existing&&new Date(existing.expires_at)>new Date()&&existing.user!==me)return {ok:false,lock:existing};const lock={user:me,locked_at:now(),expires_at:new Date(Date.now()+minutes*60000).toISOString()};all[id]=lock;write(LOCK,all);return {ok:true,lock};};
export const releaseApprovalLock=(id)=>{const all=read(LOCK,{});if(all[id]?.user===currentUser())delete all[id];write(LOCK,all)};
export const getApprovalLock=(id)=>{const all=read(LOCK,{}),l=all[id];if(!l)return null;if(new Date(l.expires_at)<=new Date()){delete all[id];write(LOCK,all);return null}return l;};
export const explainPrice=(customer)=>{const snaps=getEscalationSnapshots().filter(x=>x.customer===customer).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));return snaps.map((s,i)=>{const q=getEscalationQueue().find(x=>x.id===s.escalationId);return {step:i+1,date:s.created_at,actor:s.actor,escalationId:s.escalationId,rate:Number(q?.appliedRate||0),fuelBefore:Number(q?.oldFuel||0),fuelAfter:Number(q?.newFuel||0),affected:Number(q?.affectedRoutes||0)};});};
export const getTariffAtDate=(customer,date)=>{const target=new Date(date).getTime();const snaps=getEscalationSnapshots().filter(x=>x.customer===customer&&new Date(x.created_at).getTime()<=target).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const snap=snaps[0];if(!snap)return null;return {date:snap.created_at,snapshotId:snap.id,data:snap.after,actor:snap.actor};};
export const registerManualTariffChange=(payload)=>{const rows=read(MANUAL,[]);const item={id:`MAN-${Date.now()}`,created_at:now(),actor:currentUser(),...payload};write(MANUAL,[item,...rows].slice(0,500));return item;};
export const getManualTariffChanges=()=>read(MANUAL,[]);
export const getOperationPriorities=()=>{const q=getEscalationQueue();const rules=getContractRules();const out=[];q.filter(x=>['pending','postponed','suspicious'].includes(x.status)).forEach(x=>out.push({type:'approval',severity:(Date.now()-new Date(x.created_at))/3600000>=6?'critical':'warning',customer:x.customer,title:`${x.customer} onay bekliyor`,detail:`${getPackage(x.id)?.id||x.id} · %${Number(x.appliedRate||0).toFixed(2)} tarife etkisi`,id:x.id}));Object.keys(rules).forEach(c=>{const p=thresholdProgress(c);if(p.state==='near')out.push({type:'threshold',severity:'info',customer:c,title:`${c} eşiğe yaklaşıyor`,detail:`%${p.current.toFixed(2)} / %${p.threshold} · ${p.remaining.toFixed(2)} puan kaldı`,id:`thr-${c}`})});return out.sort((a,b)=>({critical:0,warning:1,info:2}[a.severity]-({critical:0,warning:1,info:2}[b.severity])));};
export const getAuditForPackage=(escalationId)=>getEscalationAudit().filter(x=>x.escalationId===escalationId);

const PREFS='odak_yakit_notification_preferences_v5';
export const getFuelNotificationPreferences=()=>read(PREFS,{inApp:true,email:true,approval:true,threshold:true,health:true,dailySummary:false});
export const saveFuelNotificationPreferences=(prefs)=>{write(PREFS,prefs);window.dispatchEvent(new Event('odak-escalation-changed'));return prefs};
export const getFuelDataQuality=()=>{const q=getEscalationQueue(),rules=getContractRules(),issues=[];Object.entries(rules).forEach(([customer,r])=>{if(!(Number(r.threshold)>0))issues.push({level:'critical',customer,title:'Eşik tanımsız',detail:'Müşteri kuralında geçerli eşik yok.'});if(!(Number(r.factor)>0))issues.push({level:'critical',customer,title:'Yansıtma oranı tanımsız',detail:'Müşteri kuralında geçerli yansıtma oranı yok.'});if(!r.provider)issues.push({level:'warning',customer,title:'Referans kaynak eksik',detail:'Yakıt sağlayıcısı tanımlanmamış.'});if(!r.location)issues.push({level:'warning',customer,title:'Lokasyon eksik',detail:'Referans lokasyon tanımlanmamış.'})});q.forEach(x=>{if(!Number.isFinite(Number(x.newFuel))||Number(x.newFuel)<=0)issues.push({level:'critical',customer:x.customer,title:'Geçersiz yakıt fiyatı',detail:`${x.id} kaydında yeni yakıt fiyatı kontrol edilmeli.`});});return {checked:Object.keys(rules).length,issues,critical:issues.filter(x=>x.level==='critical').length,warning:issues.filter(x=>x.level==='warning').length};};
export const getFuelReadinessChecklist=()=>{const quality=getFuelDataQuality(),health=Object.values(read('odak_fuel_source_health_v3',{}));const q=getEscalationQueue();return [{id:'rules',label:'Müşteri kuralları tanımlı',ok:quality.critical===0,detail:quality.critical?`${quality.critical} kritik kural/veri sorunu var`:'Kritik kural sorunu yok'},{id:'health',label:'Yakıt kaynakları sağlıklı',ok:!health.some(x=>x.status==='error'||x.status==='failed'),detail:health.length?`${health.length} kaynak izleniyor`:'Henüz sağlık kaydı yok'},{id:'pending',label:'Bekleyen işlemler kontrol altında',ok:q.filter(x=>['pending','postponed','suspicious'].includes(x.status)).length<10,detail:`${q.filter(x=>['pending','postponed','suspicious'].includes(x.status)).length} aktif işlem`},{id:'snapshots',label:'Geri dönüş snapshot altyapısı hazır',ok:Array.isArray(getEscalationSnapshots()),detail:`${getEscalationSnapshots().length} snapshot kayıtlı`}];};
export const buildFuelAuditCsv=()=>{const rows=getEscalationAudit();const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';return ['Tarih,Müşteri,Olay,Kullanıcı,Onay ID',...rows.map(x=>[x.created_at,x.customer,x.event||x.action||x.type,x.actor,x.escalationId].map(esc).join(','))].join('\n')};
